def parse_steps(spec):
  """'1,3-5' -> [1, 3, 4, 5]"""
  steps = []
  for part in spec.split(','):
    if '-' in part:
      lo, hi = part.split('-')
      steps.extend(range(int(lo), int(hi) + 1))
    elif part.strip():
      steps.append(int(part))
  return steps

